const body = $json.body ?? {};
const errors = [];
const allowedActions = ["approve", "reject", "cancel"];

function requirePositiveInteger(field, label) {
  const value = Number(body[field]);
  if (!Number.isInteger(value) || value < 1) errors.push(label + " must be a positive number");
  return value;
}

function requireAction(field, label) {
  const value = String(body[field] ?? "").trim().toLowerCase();
  if (!allowedActions.includes(value)) errors.push(label + " is invalid");
  return value;
}

const id = requirePositiveInteger("id", "Post ID");
const action = requireAction("action", "Review action");

if (errors.length > 0) {
  return [{ json: { valid: false, response: { success: false, message: "Validation failed", error: errors.join("; ") } } }];
}

return [{ json: { valid: true, body: { id, action } } }];

